import type { BusinessOutcome, BusinessStepDetail, ExecutionFacts, ReportHistoryPoint, TestType } from '../analytics/report.types';
import { formatTestType } from '../analytics/test-layer.classifier';
import { deriveExplainableReleaseRisk } from '../analytics/evidence-graph';
import type { AiProviderHealthSummary } from '../ai/ai-provider-health.store';
import type { AgenticIntelligenceSummary } from '../agentic/evidence/agent-decision-ledger';

export interface BusinessDashboardOptions {
  history?: ReportHistoryPoint[];
  reportUrl?: string;
  providerHealth?: AiProviderHealthSummary;
  agenticSummary?: AgenticIntelligenceSummary;
}

interface ChartItem { label: string; value: number }

/**
 * Author: Raushan Raj
 * Business Use: Renders an executive-first release-health dashboard with engineering drill-down.
 * How to use: Generated by BusinessReporter or `npm run report:dashboard`; use `npm run report:serve` for the full interactive experience.
 * Benefit: Separates quality debt, accepted known defects and CI-blocking issues while retaining Playwright-grade steps/evidence for investigation.
 */
export function renderBusinessHtml(payload: ExecutionFacts, options: BusinessDashboardOptions = {}): string {
  const history = options.history ?? [];
  const providerHealth = options.providerHealth ?? { status: 'SKIPPED' as const, samples: 0, healthySamples: 0, degradedSamples: 0, availabilityPercent: null, averageGenerationLatencyMs: null, recent: [] };
  const agenticSummary = options.agenticSummary ?? { status: 'NO_ACTIVITY' as const, decisions: 0, trusted: 0, rejected: 0, reviewRequired: 0, insufficientEvidence: 0, degraded: 0, agents: { planner: 0, generator: 0, reviewer: 0, healer: 0, mcp: 0 } };
  const aiUsage = payload.aiUsage ?? { calls: 0, healingCalls: 0, reportingCalls: 0, successfulCalls: 0, noResultCalls: 0, errorCalls: 0, budgetBlockedCalls: 0, averageLatencyMs: 0, providers: [], records: [] };
  const healingAttempts = payload.healing.attempts ?? payload.healing.records;
  const skipBreakdown = payload.skipBreakdown ?? { count: payload.skipped, categories: [] };
  const projectOptions = unique(payload.results.map(result => result.project));
  const tagOptions = unique(payload.results.flatMap(result => result.tags));
  const categoryOptions = unique(payload.results.map(result => result.failureCategory).filter(Boolean) as string[]);
  const typeOptions = unique(payload.results.map(result => result.testType ?? 'OTHER')) as TestType[];
  const outcomeOptions = unique(payload.results.map(result => result.outcome ?? legacyOutcome(result.status))) as BusinessOutcome[];
  const normalPassed = payload.outcomes.cleanPassed + payload.outcomes.passedWithHealing + payload.outcomes.passedAfterRetry;
  const statusData: ChartItem[] = [
    { label: 'Passed', value: normalPassed },
    { label: 'Known Defect', value: payload.knownDefects },
    { label: 'Failed', value: payload.unexpectedFailed },
    { label: 'Unexpected Pass', value: payload.unexpectedPass },
    { label: 'Not Applicable', value: payload.notApplicable },
    { label: 'Blocked', value: payload.blockedSkipped }
  ].filter(item => item.value > 0 || item.label === 'Passed');
  const layerData: ChartItem[] = [
    { label: 'UI', value: payload.layerCounts.UI },
    { label: 'API', value: payload.layerCounts.API },
    { label: 'Database', value: payload.layerCounts.DATABASE },
    { label: 'Other', value: payload.layerCounts.OTHER }
  ];
  const failureData: ChartItem[] = Object.entries(payload.failureCategoryCounts).map(([label, value]) => ({ label, value }));
  const slowest = [...payload.results].filter(result => result.status !== 'skipped').sort((a, b) => b.totalDurationMs - a.totalDurationMs).slice(0, 5);
  const knownDefectResults = payload.results.filter(result => result.outcome === 'KNOWN_DEFECT' || result.outcome === 'UNEXPECTED_PASS');

  const rows = payload.results.map(result => renderScenarioRow(result, payload)).join('');
  const clusterCards = payload.failureClusters.length
    ? payload.failureClusters.map(cluster => `<article class="insight-card"><div class="insight-top"><span class="badge danger">${escapeHtml(cluster.category)}</span><b>${cluster.affectedTests} affected</b></div><h3>${escapeHtml(cluster.evidence)}</h3><p>${cluster.testTitles.map(escapeHtml).join('<br>')}</p></article>`).join('')
    : emptyState('No new failure clusters', 'No unexpected final failure cluster requires investigation in this business scope.');
  const impactCards = payload.businessImpacts.length
    ? payload.businessImpacts.map(impact => `<article class="insight-card"><div class="insight-top"><span class="badge ${impact.priority === 'HIGH' ? 'danger' : impact.priority === 'MEDIUM' ? 'warn' : 'success'}">${impact.priority}</span><b>${impact.affectedTests} affected</b></div><h3>${escapeHtml(impact.area)}</h3><p>${escapeHtml(impact.impact)}</p></article>`).join('')
    : emptyState('No mapped business impact', 'No configured business-impact rule matched a quality-failed scenario.');
  const knownDefectRows = knownDefectResults.length
    ? knownDefectResults.map(result => `<tr><td><b>${escapeHtml(result.knownDefect?.id ?? 'UNREGISTERED')}</b></td><td>${escapeHtml(result.knownDefect?.title ?? result.title)}</td><td>${escapeHtml(result.knownDefect?.scope ?? '—')}</td><td><span class="badge ${result.outcome === 'UNEXPECTED_PASS' ? 'info' : 'known'}">${escapeHtml(formatOutcome(result.outcome ?? 'KNOWN_DEFECT'))}</span></td><td>${escapeHtml(result.knownDefect?.note ?? '—')}</td><td>${escapeHtml(result.title)}</td></tr>`).join('')
    : '';
  const healingRows = healingAttempts.map(record => {
    const outcome = record.outcome ?? 'validated';
    const verification = record.verification?.description ?? (outcome === 'validated' ? 'Historical validated recovery' : '—');
    return `<tr><td>${escapeHtml(record.businessName)}</td><td><span class="badge ${outcome === 'validated' ? 'success' : outcome === 'rejected' ? 'danger' : 'muted-badge'}">${escapeHtml(outcome.toUpperCase())}</span></td><td>${escapeHtml(record.decision.source.toUpperCase())}</td><td>${escapeHtml(record.decision.aiProvider ?? '—')}</td><td>${escapeHtml(record.decision.aiModel ?? '—')}</td><td>${Math.round(record.decision.confidence * 100)}%</td><td>${escapeHtml(verification)}</td><td>${escapeHtml(record.decision.reason)}</td></tr>`;
  }).join('');
  const aiRows = aiUsage.records.map(record => `<tr><td>${escapeHtml(record.purpose)}</td><td>${escapeHtml(record.status)}</td><td>${escapeHtml(record.provider ?? '—')}</td><td>${escapeHtml(record.model ?? '—')}</td><td>${record.latencyMs === undefined ? '—' : `${record.latencyMs} ms`}</td><td>${escapeHtml(record.testId ?? 'run-level')}</td></tr>`).join('');
  const flakyRows = payload.flakiness.tests.map(test => `<tr><td>${escapeHtml(test.title)}</td><td>${escapeHtml(test.project)}</td><td>${test.attempts.map(attempt => `#${attempt.retry}: ${escapeHtml(attempt.status)}`).join('<br>')}</td></tr>`).join('');
  const skipRows = skipBreakdown.categories.map(item => `<tr><td><span class="badge muted-badge">${escapeHtml(item.label)}</span></td><td>${escapeHtml(item.disposition.replaceAll('_', ' '))}</td><td>${item.count}</td><td>${item.reasons.length ? item.reasons.map(escapeHtml).join('<br>') : 'No explicit reason captured'}</td><td>${item.testTitles.map(escapeHtml).join('<br>')}</td></tr>`).join('');
  const excluded = payload.scope?.excludedInternalTests ?? 0;
  const qualityDenominator = payload.outcomes.qualityPassed + payload.qualityFailed;
  const executionCoverageDisplay = payload.executionEligible > 0 ? `${payload.executionRate}% applicable execution coverage` : 'No applicable execution denominator';
  const qualityPassDisplay = qualityDenominator > 0 ? `${payload.qualityPassRate}%` : 'N/A';
  const dataJson = safeJson({ history, reportUrl: options.reportUrl ?? process.env.REPORT_PUBLIC_URL ?? '' });
  const gate = payload.total === 0
    ? { label: 'INSUFFICIENT EVIDENCE', className: 'attention', description: 'No reported business scenarios are available, so TestigentAI refuses to infer release readiness.' }
    : gatePresentation(payload.qualityGate.status);
  const releaseRisk = deriveExplainableReleaseRisk(payload);

  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TestigentAI Release Quality Dashboard</title><style>${styles()}</style></head><body><main class="shell">
<section class="hero"><div class="hero-top"><div><div class="eyebrow">TESTIGENTAI · RELEASE QUALITY</div><h1>Business Quality Dashboard</h1><p>Release health, accepted risk and execution signals in one decision-ready view. Technical proof stays one click away.</p><div class="hero-actions"><a class="evidence-cta" href="./evidence-ledger.html">Verify dashboard claims ↗</a><a class="evidence-cta secondary-dark" href="./agentic-intelligence.html">Agentic intelligence ↗</a><a class="evidence-cta secondary-dark" href="./adoption-intelligence.html">Adoption evidence ↗</a><a class="evidence-cta secondary-dark" href="./benchmark-intelligence.html">Benchmark evidence ↗</a><a class="evidence-cta secondary-dark" href="./api-contract-intelligence.html">API contracts ↗</a><a class="evidence-cta secondary-dark" href="./evidence-graph.json" download>Evidence graph JSON</a></div></div><span class="gate ${gate.className}">${gate.label}</span></div><div class="meta"><span>Run ${escapeHtml(payload.runId)}</span><span>Environment ${escapeHtml(payload.environment)}</span><span>Application ${escapeHtml(payload.application)}</span><span>Generated ${escapeHtml(formatDate(payload.generatedAt))}</span><span>Quality target ${payload.qualityGate.passThreshold}%</span>${payload.aggregation ? `<span>${payload.aggregation.mode === 'merged' ? `Merged ${payload.aggregation.sourceReports} report bundle(s) · core ${payload.aggregation.coreReports ?? payload.aggregation.sourceReports} · AI ${payload.aggregation.aiReports ?? 0} · AI results ${payload.aggregation.aiResults ?? 0}` : 'Single execution bundle'}</span>` : ''}</div><div class="scope-note">Selected business scenarios: ${payload.total} · applicable: ${payload.executionEligible} · executed: ${payload.executed} · not applicable: ${payload.notApplicable} · blocked: ${payload.blockedSkipped} · ${excluded} framework/internal check(s) excluded.</div></section>
<section class="kpis executive-kpis">${kpi('Selected', payload.total, `${payload.executionEligible} applicable · ${payload.notApplicable} not applicable`, 'neutral')}${kpi('Executed', payload.executionEligible > 0 ? `${payload.executed}/${payload.executionEligible}` : 'N/A', executionCoverageDisplay, payload.executionEligible > 0 && payload.executionRate === 100 ? 'success' : 'warn')}${kpi('Quality pass rate', qualityPassDisplay, qualityDenominator > 0 ? `${payload.outcomes.qualityPassed}/${qualityDenominator} quality-executed passed` : 'No quality-executed denominator', qualityDenominator > 0 ? toneForRate(payload.qualityPassRate, payload.qualityGate.passThreshold) : 'warn', 'quality-pass-rate')}${kpi('Quality failed', payload.qualityFailed, `${payload.knownDefects} known · ${payload.unexpectedFailed} unexpected`, payload.qualityFailed ? 'danger' : 'success')}${kpi('Known defects', payload.knownDefects, 'Accepted quality debt; counted as quality failed', payload.knownDefects ? 'known' : 'neutral')}${kpi('CI-blocking issues', payload.ciBlockingIssues, `${payload.unexpectedFailed} failures · ${payload.unexpectedPass} unexpected pass`, payload.ciBlockingIssues ? 'danger' : 'success', 'ci-blockers')}${kpi('Not applicable', payload.notApplicable, 'Excluded from execution coverage denominator', payload.notApplicable ? 'neutral' : 'success')}${kpi('Flaky', payload.flakiness.flakyTests, `${payload.flakiness.totalRetryAttempts} retry attempt(s)`, payload.flakiness.flakyTests ? 'warn' : 'success')}${kpi('Self-healed', payload.healing.count, `${payload.healing.ai} AI validated · ${payload.healing.rejected ?? 0} rejected`, payload.healing.count ? 'info' : 'neutral', 'validated-healing')}</section>
<section class="grid section-space">
<div class="panel span4 print-chart-panel"><div class="panel-head"><div><h2>Quality outcome</h2><div class="panel-sub">Known defects are shown separately but included in quality failed.</div></div></div><div class="donut-wrap"><div id="statusDonut" class="status-donut">${renderStatusDonutSvg(statusData, qualityPassDisplay)}</div><div id="statusLegend" class="legend">${renderLegend(statusData)}</div></div></div>
<div class="panel span4"><div class="panel-head"><div><h2>Action queue</h2><div class="panel-sub">ReportPortal-style separation of understood debt vs items needing investigation.</div></div></div><div class="action-grid">${actionMetric('Investigate now', payload.outcomes.toInvestigate, 'Unexpected failures + unexpected passes', payload.outcomes.toInvestigate ? 'danger' : 'success')}${actionMetric('Accepted defect debt', payload.outcomes.acceptedDefectDebt, 'Registered known defects', payload.outcomes.acceptedDefectDebt ? 'known' : 'success')}${actionMetric('Flaky / retry recovered', payload.flakiness.flakyTests, 'Stability debt', payload.flakiness.flakyTests ? 'warn' : 'success')}${actionMetric('Rejected healing', payload.healing.rejected ?? 0, 'Diagnostic evidence only', payload.healing.rejected ? 'warn' : 'neutral')}</div></div>
<div class="panel span4"><div class="panel-head"><div><h2>Release decision</h2><div class="panel-sub">Deterministic gate plus score-free risk factors; CI status and business quality remain distinct.</div></div><a class="proof-link" href="./evidence-ledger.html#claim-release-decision">Verify ↗</a></div><div class="decision ${gate.className}"><b>${gate.label}</b><p>${escapeHtml(gate.description)}</p><p><b>Release risk:</b> ${escapeHtml(releaseRisk.level)} · <b>evidence:</b> ${escapeHtml(releaseRisk.evidenceConfidence)}</p></div><div class="reason-list">${releaseRisk.factors.map(reason => `<div class="reason"><span>•</span><span>${escapeHtml(reason)}</span></div>`).join('')}</div><a class="proof-link" href="./evidence-ledger.html#claim-release-risk">Verify risk factors ↗</a></div>
<div class="panel span8"><div class="panel-head"><div><h2>Quality trend</h2><div class="panel-sub">Allure-style run history using quality pass rate (skips excluded, known defects counted as failed).</div></div></div>${renderTrendSvg(history)}</div>
<div class="panel span4"><div class="panel-head"><div><h2>Slowest scenarios</h2><div class="panel-sub">Top execution-cost drivers for this run.</div></div></div>${slowest.length ? `<div class="rank-list">${slowest.map((result, index) => `<div class="rank-row"><span class="rank">${index + 1}</span><span><b>${escapeHtml(shortTitle(result.title))}</b><small>${escapeHtml(formatOutcome(result.outcome ?? legacyOutcome(result.status)))}</small></span><strong>${formatDuration(result.totalDurationMs)}</strong></div>`).join('')}</div>` : emptyState('No executed scenarios', 'No duration data available.')}</div>
<div class="panel span4"><div class="panel-head"><div><h2>Executed layer coverage</h2><div class="panel-sub">Executed business scenarios only; not-applicable and blocked skips are excluded.</div></div></div><div id="layerBars" class="bars">${renderBars(layerData)}</div></div>
<div class="panel span4"><div class="panel-head"><div><h2>Quality failure categories</h2><div class="panel-sub">Includes known-defect debt and unexpected failures.</div></div></div><div id="failureBars" class="bars">${renderBars(failureData)}</div></div>
<div class="panel span4"><div class="panel-head"><div><h2>Reliability signals</h2><div class="panel-sub">Signals that may not fail the release but deserve engineering attention.</div></div><div><a class="proof-link" href="./ai-provider-health.html">AI provider health ↗</a><br><a class="proof-link" href="./agentic-intelligence.html">Agentic decisions ↗</a><br><a class="proof-link" href="./adoption-intelligence.html">Adoption evidence ↗</a><br><a class="proof-link" href="./benchmark-intelligence.html">Benchmark evidence ↗</a><br><a class="proof-link" href="./api-contract-intelligence.html">API contracts ↗</a></div></div><div class="signal-list"><div><span>Passed with healing</span><b>${payload.outcomes.passedWithHealing}</b></div><div><span>Passed after retry</span><b>${payload.outcomes.passedAfterRetry}</b></div><div><span>AI runtime calls</span><b>${aiUsage.calls}</b></div><div><span>Live AI provider</span><b>${escapeHtml(providerHealth.status)}</b></div><div><span>Agentic decisions</span><b>${agenticSummary.decisions}</b></div><div><span>Agentic state</span><b>${escapeHtml(agenticSummary.status)}</b></div></div></div>
</section>
<section class="panel section-space"><div class="panel-head"><div><h2>Business impact</h2><div class="panel-sub">Risk translated from quality-failed scenarios into business language.</div></div></div><div class="insight-grid">${impactCards}</div></section>
<section class="panel section-space"><div class="panel-head"><div><h2>New failure clusters</h2><div class="panel-sub">Unexpected failures grouped for triage; accepted known defects are tracked separately.</div></div></div><div class="insight-grid">${clusterCards}</div></section>
${knownDefectResults.length ? `<section class="panel section-space"><div class="panel-head"><div><h2>Known defects &amp; accepted risk</h2><div class="panel-sub">These scenarios count as quality failures. Expected failures are non-blocking only because the defect is explicitly registered.</div></div></div><div class="table-wrap"><table><thead><tr><th>Defect</th><th>Title</th><th>Scope</th><th>Outcome</th><th>Business / QA note</th><th>Scenario</th></tr></thead><tbody>${knownDefectRows}</tbody></table></div></section>` : ''}
<section class="panel section-space"><div class="panel-head"><div><h2>Test Explorer</h2><div class="panel-sub">Allure/Playwright-style drill-down: filter by business outcome, layer and risk signal, then expand a scenario for exact steps and evidence.</div></div><div class="actions"><button class="button secondary" id="resetBtn" type="button">Reset filters</button><button class="button secondary" id="expandBtn" type="button">Expand steps</button><button class="button secondary" id="collapseBtn" type="button">Collapse steps</button><button class="button secondary" id="printBtn" type="button">Print / PDF</button><button class="button" id="exportBtn" type="button">Export filtered CSV</button><a class="button secondary link-button" href="./business-tests.csv" download>Download all CSV</a></div></div>
<div class="filters"><input id="searchFilter" placeholder="Search scenario, defect, file or tag…"><select id="statusFilter"><option value="">All outcomes</option>${outcomeOptions.map(outcome => `<option value="${outcome.toLowerCase()}">${escapeHtml(formatOutcome(outcome))}</option>`).join('')}</select><select id="layerFilter"><option value="">All layers</option><option value="ui">UI involved</option><option value="api">API involved</option><option value="database">Database involved</option></select><select id="typeFilter"><option value="">All test types</option>${typeOptions.map(type => `<option value="${type.toLowerCase()}">${escapeHtml(formatTestType(type))}</option>`).join('')}</select><select id="projectFilter"><option value="">All browsers/projects</option>${projectOptions.map(project => `<option value="${project.toLowerCase()}">${escapeHtml(project)}</option>`).join('')}</select><select id="tagFilter"><option value="">All tags</option>${tagOptions.map(tag => `<option value="${tag.toLowerCase()}">${escapeHtml(tag)}</option>`).join('')}</select><select id="categoryFilter"><option value="">All failure categories</option>${categoryOptions.map(category => `<option value="${category.toLowerCase()}">${escapeHtml(category)}</option>`).join('')}</select><select id="specialFilter"><option value="">All signals</option><option value="ci-blocking">CI blocking</option><option value="known-defect">Known defect</option><option value="flaky">Flaky</option><option value="healed">Self-healed</option></select><select id="sortFilter"><option value="default">Original order</option><option value="status">Risk first</option><option value="duration-desc">Slowest first</option><option value="retries-desc">Most retries</option><option value="name">Scenario A-Z</option></select></div>
<div class="toolbar-line"><div id="showing" class="subtle">Showing ${payload.results.length} of ${payload.results.length} business scenarios</div><div class="filtered-kpis"><span id="filteredPass" class="mini-kpi">Pass ${normalPassed}</span><span id="filteredKnown" class="mini-kpi known-mini">Known ${payload.knownDefects}</span><span id="filteredFail" class="mini-kpi">Fail ${payload.unexpectedFailed}</span><span id="filteredSkip" class="mini-kpi">Skip ${payload.skipped}</span></div><span id="dashboardJsStatus" class="runtime-state">Interactive controls loading…</span></div>
<div class="table-wrap"><table id="testsTable"><thead><tr><th>Business scenario</th><th>Outcome</th><th>Type</th><th>Project</th><th>Tags</th><th>Duration</th><th>Retries</th><th>Failure category</th></tr></thead><tbody>${rows}</tbody></table></div></section>
${skipBreakdown.count ? `<section class="panel section-space"><div class="panel-head"><div><h2>Non-execution breakdown</h2><div class="panel-sub">Not-applicable scenarios do not reduce execution coverage; blocked scenarios do.</div></div></div><div class="table-wrap"><table><thead><tr><th>Category</th><th>Treatment</th><th>Count</th><th>Reason</th><th>Scenarios</th></tr></thead><tbody>${skipRows}</tbody></table></div></section>` : ''}
<section class="panel section-space"><details class="advanced"><summary>Engineering diagnostics · healing, AI and flaky execution</summary><div class="advanced-body"><h3>Flaky / retry-recovered tests</h3>${flakyRows ? `<div class="table-wrap"><table><thead><tr><th>Scenario</th><th>Project</th><th>Attempts</th></tr></thead><tbody>${flakyRows}</tbody></table></div>` : emptyState('No flaky tests', 'No scenario recovered after retry in this run.')}<h3>Healing audit</h3>${healingRows ? `<div class="table-wrap"><table><thead><tr><th>Business action</th><th>Outcome</th><th>Source</th><th>Provider</th><th>Model</th><th>Confidence</th><th>Verification</th><th>Reason</th></tr></thead><tbody>${healingRows}</tbody></table></div>` : emptyState('No healing attempts', 'No locator recovery was attempted.')}<h3>AI runtime audit</h3>${aiRows ? `<div class="table-wrap"><table><thead><tr><th>Purpose</th><th>Status</th><th>Provider</th><th>Model</th><th>Latency</th><th>Test</th></tr></thead><tbody>${aiRows}</tbody></table></div>` : emptyState('No AI runtime calls', 'No AI provider was invoked for this run.')}</div></details></section>
<div class="trust section-space"><b>Trust model:</b> quality status, defect debt, retries, failure clusters, layer classification and healing totals are deterministic framework facts. A known defect counts as quality failed but is non-blocking only when explicitly registered. Only semantically validated recoveries count as self-healed. AI may explain evidence but cannot change these facts.</div>
<footer class="footer">TestigentAI · Intelligent Quality Engineering Platform · Author: Raushan Raj</footer>
<script id="dashboardData" type="application/json">${dataJson}</script><script src="./assets/dashboard.js"></script></main></body></html>`;
}

function renderScenarioRow(result: ExecutionFacts['results'][number], payload: ExecutionFacts): string {
  const healingForTest = payload.healing.records.filter(record => record.testId === result.testId);
  const outcome = result.outcome ?? legacyOutcome(result.status);
  const statusClass = outcomeClass(outcome);
  const type = result.testType ?? 'OTHER';
  const layers = result.layers ?? [];
  const tags = result.tags.length ? result.tags : ['—'];
  const defectText = result.knownDefect ? `${result.knownDefect.id} ${result.knownDefect.title} ${result.knownDefect.scope ?? ''}` : '';
  const attachments = result.attachments ?? [];
  const failedStepExists = containsFailedStep(result.stepDetails ?? []);
  const primaryFailureEvidence = failedStepExists ? selectPrimaryFailureEvidence(attachments) : [];
  const primaryEvidenceKeys = new Set(primaryFailureEvidence.map(attachmentIdentity));
  const additionalAttachments = failedStepExists
    ? attachments.filter(item => !item.contentType.startsWith('image/') && !primaryEvidenceKeys.has(attachmentIdentity(item)))
    : attachments;
  const stepDetails = result.stepDetails?.length ? renderStepTree(result.stepDetails, primaryFailureEvidence, { rendered: false }) : result.steps.length
    ? `<ol class="simple-steps">${result.steps.map(step => `<li>${escapeHtml(step)}</li>`).join('')}</ol>`
    : '<p class="subtle">No business steps captured. Add test.step() to expose the business journey.</p>';
  const evidence = renderEvidence(additionalAttachments, false);
  const evidenceHeading = failedStepExists ? 'Additional attachments' : 'Attachments';
  const defectDetails = result.knownDefect
    ? `<div class="defect-box"><b>${escapeHtml(result.knownDefect.id)} · ${escapeHtml(result.knownDefect.title)}</b><p><b>Scope:</b> ${escapeHtml(result.knownDefect.scope ?? '—')}</p>${result.knownDefect.note ? `<p>${escapeHtml(result.knownDefect.note)}</p>` : ''}<p><b>Quality impact:</b> FAILED · <b>CI impact:</b> ${result.ciBlocking ? 'BLOCKING' : 'NON-BLOCKING ACCEPTED DEFECT'}</p></div>`
    : '';
  return `<tr class="test-row" data-title="${attr(result.title.toLowerCase())}" data-file="${attr(shortFile(result.sourceFile).toLowerCase())}" data-defect="${attr(defectText.toLowerCase())}" data-status="${attr(result.status)}" data-outcome="${attr(outcome.toLowerCase())}" data-project="${attr(result.project.toLowerCase())}" data-tags="${attr(result.tags.map(tag => tag.toLowerCase()).join('|'))}" data-type="${attr(type.toLowerCase())}" data-layers="${attr(layers.join('|').toLowerCase())}" data-category="${attr((result.failureCategory ?? '').toLowerCase())}" data-skip-disposition="${attr(skipDisposition(result.skipCategory).toLowerCase())}" data-flaky="${result.flaky}" data-healed="${healingForTest.length > 0}" data-known-defect="${Boolean(result.knownDefect)}" data-ci-blocking="${Boolean(result.ciBlocking)}" data-duration="${result.totalDurationMs}" data-retries="${result.retriesUsed}">
<td><div class="scenario-title">${escapeHtml(result.title)}</div><div class="subtle">${escapeHtml(shortFile(result.sourceFile))}</div><details class="scenario-details"><summary>View execution details</summary><div class="detail-grid"><div><h4>Business test steps</h4>${stepDetails}</div><div><h4>Execution evidence</h4><p><b>Business outcome:</b> ${escapeHtml(formatOutcome(outcome))}</p><p><b>Quality:</b> ${escapeHtml(result.qualityStatus ?? '—')} · <b>CI blocking:</b> ${result.ciBlocking ? 'Yes' : 'No'}</p><p><b>Layers:</b> ${layers.length ? layers.map(escapeHtml).join(' + ') : 'Other'}</p><p><b>Retries:</b> ${result.retriesUsed}</p><p><b>Flaky:</b> ${result.flaky ? 'Yes' : 'No'}</p><p><b>Self-healed:</b> ${healingForTest.length ? `Yes (${healingForTest.length})` : 'No'}</p>${result.status === 'skipped' ? `<p><b>Skip category:</b> ${escapeHtml(result.skipCategory ?? 'OTHER')}</p><p><b>Skip reason:</b> ${escapeHtml(result.skipReason ?? 'No explicit reason captured')}</p>` : ''}${defectDetails}${result.error ? `<div class="error-box"><b>Observed failure:</b> ${escapeHtml(result.error)}</div>` : ''}<h4 class="evidence-heading">${evidenceHeading}</h4>${evidence}</div></div></details></td>
<td><span class="badge ${statusClass}">${escapeHtml(formatOutcome(outcome))}</span></td><td><span class="type-pill">${escapeHtml(formatTestType(type))}</span></td><td>${escapeHtml(result.project)}</td><td>${tags.map(tag => `<span class="tag">${escapeHtml(tag)}</span>`).join(' ')}</td><td>${formatDuration(result.totalDurationMs)}</td><td>${result.retriesUsed}</td><td>${escapeHtml(result.failureCategory ?? (outcome === 'KNOWN_DEFECT' ? 'KNOWN_DEFECT' : '—'))}</td></tr>`;
}

interface StepEvidenceRenderState { rendered: boolean }

function renderStepTree(
  steps: BusinessStepDetail[],
  failureEvidence: ExecutionFacts['results'][number]['attachments'] = [],
  evidenceState: StepEvidenceRenderState = { rendered: false },
): string {
  return `<ol class="step-tree">${steps.map(step => {
    const hasFailedChild = containsFailedStep(step.children);
    const shouldRenderFailureEvidence = step.status === 'failed' && !hasFailedChild && !evidenceState.rendered && Boolean(failureEvidence?.length);
    const failedEvidence = shouldRenderFailureEvidence ? renderEvidence(failureEvidence ?? [], true) : '';
    if (shouldRenderFailureEvidence) evidenceState.rendered = true;
    return `<li class="step ${step.status}"><div class="step-line"><span class="step-status">${step.status === 'passed' ? '✓' : step.status === 'failed' ? '✕' : '–'}</span><span class="step-title">${escapeHtml(step.title)}</span><span class="step-duration">${formatDuration(step.durationMs)}</span></div>${step.location?.file ? `<div class="step-meta subtle">${escapeHtml(shortFile(step.location.file))}${step.location.line ? `:${step.location.line}` : ''}</div>` : ''}${step.error ? `<div class="error-box">${escapeHtml(step.error)}</div>` : ''}${failedEvidence ? `<div class="step-evidence"><div class="step-evidence-title">Failure evidence</div>${failedEvidence}</div>` : ''}${step.params ? `<details class="params"><summary>Parameters</summary><pre>${escapeHtml(JSON.stringify(step.params, null, 2))}</pre></details>` : ''}${step.children.length ? renderStepTree(step.children, failureEvidence, evidenceState) : ''}</li>`;
  }).join('')}</ol>`;
}

function containsFailedStep(steps: BusinessStepDetail[]): boolean {
  return steps.some(step => step.status === 'failed' || containsFailedStep(step.children));
}

function selectPrimaryFailureEvidence(
  attachments: NonNullable<ExecutionFacts['results'][number]['attachments']>,
): NonNullable<ExecutionFacts['results'][number]['attachments']> {
  const images = attachments.filter(item => item.contentType.startsWith('image/') && Boolean(item.reportPath));
  if (!images.length) return [];
  const ranked = [...images].sort((left, right) => failureEvidenceRank(left.name) - failureEvidenceRank(right.name));
  return [ranked[0]];
}

function failureEvidenceRank(name: string): number {
  const normalized = name.toLowerCase();
  if (normalized.includes('failure-screenshot')) return 0;
  if (normalized.includes('test-failed')) return 1;
  if (normalized.includes('screenshot')) return 2;
  return 3;
}

function attachmentIdentity(item: NonNullable<ExecutionFacts['results'][number]['attachments']>[number]): string {
  return `${item.contentType}:${item.reportPath ?? item.sourcePath ?? item.name}`;
}

function renderEvidence(attachments: NonNullable<ExecutionFacts['results'][number]['attachments']>, compact: boolean): string {
  if (!attachments.length) return compact ? '' : '<p class="subtle">No shareable attachment copied for this scenario.</p>';
  const rendered = attachments.map(item => {
    if (!item.reportPath) return compact ? '' : `<div class="evidence-link muted-evidence">${escapeHtml(item.name)}<span>${escapeHtml(item.contentType)}</span></div>`;
    const href = `./${attr(item.reportPath)}`;
    if (item.contentType.startsWith('image/')) {
      return `<figure class="evidence-preview"><a href="${href}" target="_blank" rel="noopener"><img loading="lazy" src="${href}" alt="${attr(item.name)}"></a><figcaption>${escapeHtml(item.name)} · ${escapeHtml(item.contentType)}</figcaption></figure>`;
    }
    if (item.contentType.startsWith('video/')) {
      return compact
        ? `<a class="evidence-link" href="${href}" target="_blank" rel="noopener">Open ${escapeHtml(item.name)} video</a>`
        : `<figure class="evidence-preview"><video controls preload="metadata" src="${href}"></video><figcaption>${escapeHtml(item.name)} · ${escapeHtml(item.contentType)}</figcaption></figure>`;
    }
    return `<a class="evidence-link" href="${href}" target="_blank" rel="noopener">${escapeHtml(item.name)}<span>${escapeHtml(item.contentType)}</span></a>`;
  }).filter(Boolean).join('');
  return rendered || (compact ? '' : '<p class="subtle">No materialized evidence is available for this scenario.</p>');
}

function skipDisposition(category?: ExecutionFacts['results'][number]['skipCategory']): 'NOT_APPLICABLE' | 'BLOCKED' | '' {
  if (!category) return '';
  if (category === 'DATABASE_NOT_CONFIGURED' || category === 'OPTIONAL_DEMO_DISABLED') return 'NOT_APPLICABLE';
  return 'BLOCKED';
}

function gatePresentation(status: ExecutionFacts['qualityGate']['status']): { label: string; className: string; description: string } {
  if (status === 'PASSED') return { label: 'READY', className: 'pass', description: 'Quality gate passed with no accepted defect debt or CI-blocking issue.' };
  if (status === 'PASSED_WITH_ACCEPTED_RISK') return { label: 'READY · ACCEPTED RISK', className: 'accepted', description: 'No CI-blocking issue remains, but registered known defects still represent accepted quality debt.' };
  return { label: 'ATTENTION REQUIRED', className: 'attention', description: 'An unexpected failure/pass or blocked applicable scenario requires investigation before release.' };
}
function toneForRate(rate: number, threshold: number): string { return rate >= threshold ? 'success' : 'danger'; }
function outcomeClass(outcome: BusinessOutcome): string { if (outcome === 'FAILED') return 'danger'; if (outcome === 'KNOWN_DEFECT') return 'known'; if (outcome === 'SKIPPED') return 'muted-badge'; if (outcome === 'UNEXPECTED_PASS') return 'info'; if (outcome === 'PASSED_WITH_HEALING' || outcome === 'PASSED_AFTER_RETRY') return 'warn'; return 'success'; }
function legacyOutcome(status: 'passed' | 'failed' | 'skipped'): BusinessOutcome { return status === 'passed' ? 'PASSED' : status === 'failed' ? 'FAILED' : 'SKIPPED'; }
function formatOutcome(outcome: BusinessOutcome): string { return outcome.replaceAll('_', ' '); }
function shortTitle(value: string): string { const clean = value.replace(/\s+@[\w:-]+/g, ''); return clean.length > 58 ? `${clean.slice(0, 55)}…` : clean; }
function kpi(label: string, value: string | number, note: string, tone = 'neutral', claimId?: string): string { return `<div class="kpi ${tone}"><div class="kpi-label">${escapeHtml(label)}</div><div class="kpi-value">${escapeHtml(String(value))}</div><div class="kpi-note">${escapeHtml(note)}</div>${claimId ? `<a class="kpi-proof" href="./evidence-ledger.html#claim-${attr(claimId)}">Evidence ↗</a>` : ''}</div>`; }
function actionMetric(label: string, value: number, note: string, tone: string): string { return `<div class="action-card ${tone}"><span>${escapeHtml(label)}</span><b>${value}</b><small>${escapeHtml(note)}</small></div>`; }
function renderLegend(items: ChartItem[]): string { const colors: Record<string,string> = { Passed:'#059669','Known Defect':'#d97706',Failed:'#dc2626','Unexpected Pass':'#7c3aed','Not Applicable':'#94a3b8',Blocked:'#dc2626' }; return items.map(item => `<div class="legend-row"><svg class="legend-dot" viewBox="0 0 10 10" aria-hidden="true"><circle cx="5" cy="5" r="5" fill="${colors[item.label] ?? '#2563eb'}"/></svg><span>${escapeHtml(item.label)}</span><b>${item.value}</b></div>`).join(''); }
function renderBars(items: ChartItem[]): string { if (!items.length || items.every(item => item.value === 0)) return '<div class="empty">No data for this run.</div>'; const max = Math.max(1,...items.map(item=>item.value)); return items.map(item=>`<div class="bar-row"><span>${escapeHtml(item.label)}</span><span class="bar-track"><span class="bar-fill" style="width:${item.value/max*100}%"></span></span><b>${item.value}</b></div>`).join(''); }
function renderStatusDonutSvg(items: ChartItem[], qualityPassRate: number | string): string { const colors: Record<string,string> = { Passed:'#059669','Known Defect':'#d97706',Failed:'#dc2626','Unexpected Pass':'#7c3aed','Not Applicable':'#94a3b8',Blocked:'#dc2626' }; const radius=50,circumference=2*Math.PI*radius,total=items.reduce((sum,item)=>sum+item.value,0); let cursor=0; const segments=total?items.map(item=>{const length=item.value/total*circumference,offset=-cursor;cursor+=length;return `<circle class="donut-segment" data-status="${attr(item.label.toLowerCase())}" cx="60" cy="60" r="${radius}" stroke="${colors[item.label] ?? '#2563eb'}" stroke-dasharray="${length.toFixed(3)} ${(circumference-length).toFixed(3)}" stroke-dashoffset="${offset.toFixed(3)}"/>`;}).join(''):''; const qualityLabel=typeof qualityPassRate === 'number' ? `${qualityPassRate}%` : qualityPassRate; return `<svg class="status-donut-svg" viewBox="0 0 120 120" role="img" aria-label="Quality outcome: ${items.map(item=>`${item.label} ${item.value}`).join(', ')}"><circle class="donut-track" cx="60" cy="60" r="${radius}"/>${segments}<text id="donutPassRate" class="donut-rate" x="60" y="57">${escapeHtml(qualityLabel)}</text><text class="donut-label" x="60" y="72">quality pass</text></svg>`; }
function renderTrendSvg(history: ReportHistoryPoint[]): string { if(history.length<2)return '<div id="trendEmpty" class="empty">Run more executions to build a quality trend.</div>'; const W=760,H=220,P=30; const values=history.map(point=>point.qualityPassRate ?? point.passRate); const xs=history.map((_,i)=>P+i*(W-2*P)/(history.length-1)); const ys=values.map(value=>H-P-(Math.max(0,Math.min(100,value))/100)*(H-2*P)); const points=xs.map((x,i)=>`${x},${ys[i]}`).join(' '); const circles=history.map((p,i)=>`<circle cx="${xs[i]}" cy="${ys[i]}" r="5" fill="#fff" stroke="#2563eb" stroke-width="3"><title>${escapeHtml(p.runId)}: ${values[i]}% · known defects ${p.knownDefects ?? 0} · quality failed ${p.qualityFailed ?? p.failed}</title></circle>`).join(''); return `<svg id="trendChart" class="trend" viewBox="0 0 ${W} ${H}" preserveAspectRatio="none"><line x1="${P}" y1="${H-P}" x2="${W-P}" y2="${H-P}" stroke="#cbd5e1"/><line x1="${P}" y1="${P}" x2="${P}" y2="${H-P}" stroke="#cbd5e1"/><polyline fill="none" stroke="#2563eb" stroke-width="4" points="${points}"/>${circles}<text x="${P}" y="18" font-size="11" fill="#64748b">100%</text><text x="${P}" y="${H-7}" font-size="11" fill="#64748b">0%</text></svg>`; }
function emptyState(title:string,text:string):string{return `<div class="empty"><b>${escapeHtml(title)}</b><br>${escapeHtml(text)}</div>`;}
function formatDuration(ms:number):string{return ms>=1000?`${(ms/1000).toFixed(ms>=10000?0:1)} s`:`${Math.round(ms)} ms`;}
function formatDate(value:string):string{const d=new Date(value); return Number.isNaN(d.getTime())?value:d.toLocaleString('en-GB');}
function shortFile(value?:string):string{return value?value.replace(process.cwd()+'/',''):'—';}
function unique<T>(values:T[]):T[]{return [...new Set(values)].sort() as T[];}
function escapeHtml(value:string):string{return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]??c));}
function attr(value:string):string{return escapeHtml(value);}
function safeJson(value:unknown):string{return JSON.stringify(value).replace(/</g,'\\u003c').replace(/>/g,'\\u003e').replace(/&/g,'\\u0026');}

